    for ( String part : relativeParts ) {
        if ( part.equals( ".." ) ) {
            if ( pathIndex > 0 ) {
                pathIndex--;
            }
        } else if ( !part.equals( "." ) && !part.isEmpty() ) {
            pathParts[++pathIndex] = part;
        }
    }

    StringBuilder result = new StringBuilder();
    for ( int i = 0; i <= pathIndex; i++ ) {
        if ( i > 0 ) {
            result.append( "/" );
        }
        result.append( pathParts[i] );
    }

    return result.toString();
}

